# =====================================================================
# 段間同調（逓倍、+5VT）2026-10-29 スプリアス対策
# =====================================================================
# 段 1〜3 の XOR 出力を 1k（段 3 は 470Ω）で LC 並列共振（Q 約 5、調整なし）に入れて正弦波にし、自己バイアスの 74HCU04 で
# 平均値を境に矩形へ戻す → デューティが 50% にそろい、前の段の遅延ずれ（入力周波数の成分）が約 16dB 下がる。
# シミュレーションでは、同調がないと部品のばらつきで ×16 の出力のエッジが欠ける（200 台中 160 台）のが 0 台になった
B = '逓倍'
# L は秋月のマイクロインダクタ（1・4.7・10µH）。同調 3 は L が小さいので駆動を 470Ω にして Q をそろえる
for k, (xo, rv, lv, cv, f) in enumerate([('X2', '1k', '10uH', '180p', '3.66'), ('X4', '1k', '4.7uH', '100p', '7.33'),
                                         ('X8', '470', '1uH', '120p', '14.65')]):
    tk, sq, so = 'TK%d' % (k + 1), 'SQ%d' % (k + 1), 'SQO%d' % (k + 1)
    R(B, rv, xo, tk, '同調 %d（%sMHz）の駆動。Q 約 5 を決める' % (k + 1, f))
    Lx(B, lv, tk, G, '同調 %d（%sMHz）。マイクロインダクタ（Q 40 程度）、±10%% 品で可' % (k + 1, f))
    C(B, cv, tk, G, 'NP0。同調 %d（%sMHz、配線と 74HCU04 の入力を含めて）' % (k + 1, f), fp=FP_CS)
    C(B, '1000p', tk, sq, '', fp=FP_CS)
    R(B, '1M', sq, so, '自己バイアス（しきい値 = 入力の平均）')
add(B, '74xx:74HC04', '74HCU04', FP_DIP14,
    {'1': 'SQ1', '2': 'SQO1', '3': 'SQ2', '4': 'SQO2', '5': 'SQ3', '6': 'SQO3', '9': G, '8': None,
     '11': G, '10': None, '13': G, '12': None, '7': G, '14': '+5VT'},
    'アンバッファ品（必ず U 付き）。1〜3: 同調 1〜3 の後の自己バイアス増幅。4〜6 回路目は未使用')
C(B, '0.1u', '+5VT', G)
add(B, '74xx:74HC14', '74AC14', FP_DIP14,
    {'1': 'SQO3', '2': 'X8S', '3': G, '4': None, '5': G, '6': None,
     '9': G, '8': None, '11': G, '10': None, '13': G, '12': None, '7': G, '14': '+5VT'},
    '同調 3 の後の整形（シュミット）。2〜6 回路目は未使用。必ず AC 品')
C(B, '0.1u', '+5VT', G)
TP(B, 'X16', 'X16', '×16 の出力（29.3MHz、PLL の基準）の観測点')

