add(B, 'Amplifier_Operational:MCP6002-xP', 'MCP6002', FP_DIP8,
    {'3': 'LF_NI', '2': 'LF_INV', '1': 'LF_OUT', '5': G, '6': 'LF_B', '7': 'LF_B', '8': '+5VT', '4': G},
    'A: ループフィルタ（レール・ツー・レール出力 0〜5V）、B: 未使用（ボルテージフォロワで固定）')
C(B, '0.1u', '+5VT', G)
